import{_ as o,o as r,c as a,a5 as l}from"./chunks/framework.BqnnR8ku.js";const u=JSON.parse('{"title":"项目管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/projects.md","filePath":"zh/guide/projects.md"}'),d={name:"zh/guide/projects.md"};function e(i,t,s,n,h,g){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="项目管理" tabindex="-1">项目管理 <a class="header-anchor" href="#项目管理" aria-label="Permalink to &quot;项目管理&quot;">​</a></h1><p>项目是组织一次翻译工作的基本单位：语言方向、源文件（资源）、术语表与翻译作业都挂在项目下。</p><p>尚未跑通第一次翻译？请先看 <a href="/LinguaFlow/zh/guide/getting-started.html">快速开始 · Web</a>。名词解释见 <a href="/LinguaFlow/zh/guide/concepts.html">核心概念</a>。</p><h2 id="创建项目" tabindex="-1">创建项目 <a class="header-anchor" href="#创建项目" aria-label="Permalink to &quot;创建项目&quot;">​</a></h2><ol><li>打开 <strong>项目</strong> 页，点击 <strong>新建项目</strong></li><li>填写项目信息： <ul><li><strong>项目名称</strong> — 用于标识项目（最多 80 个字符）</li><li><strong>源语言</strong> — 源文件语言，可用 <code>auto</code> 自动识别</li><li><strong>目标语言</strong> — 要译成的语言</li><li><strong>启用术语表</strong> — 是否在翻译时应用术语规则</li></ul></li><li><strong>选择存储空间</strong>（服务器模式）— 明确选择项目文件保存的空间，系统不会自动替你选；无可用空间或空间不可选时会标注原因（维护中、额度不足等），详见 <a href="/LinguaFlow/zh/guide/storage.html#新建项目选择存储空间">存储管理 · 新建项目</a></li><li>点击 <strong>创建</strong>，再点进项目卡片进入工作区</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>创建后可随时改名称、语言与术语表开关。本地模式下你就是唯一用户，无需关心组织归属。</p></div><h3 id="支持的语言" tabindex="-1">支持的语言 <a class="header-anchor" href="#支持的语言" aria-label="Permalink to &quot;支持的语言&quot;">​</a></h3><table tabindex="0"><thead><tr><th>代码</th><th>语言</th></tr></thead><tbody><tr><td><code>auto</code></td><td>自动识别（仅限源语言）</td></tr><tr><td><code>en</code></td><td>英语</td></tr><tr><td><code>zh-Hans</code></td><td>简体中文</td></tr><tr><td><code>zh-Hant</code></td><td>繁体中文</td></tr><tr><td><code>ja</code></td><td>日语</td></tr><tr><td><code>ko</code></td><td>韩语</td></tr><tr><td><code>es</code></td><td>西班牙语</td></tr><tr><td><code>fr</code></td><td>法语</td></tr><tr><td><code>de</code></td><td>德语</td></tr><tr><td><code>pt</code></td><td>葡萄牙语</td></tr><tr><td><code>ru</code></td><td>俄语</td></tr><tr><td><code>ar</code></td><td>阿拉伯语</td></tr><tr><td><code>it</code></td><td>意大利语</td></tr></tbody></table><h3 id="项目归属-服务器模式-·-预览" tabindex="-1">项目归属（服务器模式 · 预览） <a class="header-anchor" href="#项目归属-服务器模式-·-预览" aria-label="Permalink to &quot;项目归属（服务器模式 · 预览）&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">预览</p><p>组织与多用户归属依赖服务器模式，该模式仍在完善。个人本地使用时项目都归属你自己，无需关心组织。</p></div><ul><li><strong>个人项目</strong> — 归属当前用户</li><li><strong>组织项目</strong> — 归属组织，同组织成员按角色协作</li></ul><p>服务器模式下，列表页顶部提供<strong>组织作用域切换</strong>（个人 / 各组织），切换后项目、AI 后端、提示词模板、执行配置等资源列表都按所选范围展示。项目编辑抽屉中可将项目复制到你有写权限的组织（<strong>复制到组织</strong>），方便把个人成果沉淀为团队资产。</p><p>组织与成员管理见账号设置中心的 <strong>团队</strong> 页：创建 / 编辑组织、按用户名添加成员、调整成员角色（所有者 / 成员）、移除成员或退出组织。</p><h2 id="项目列表" tabindex="-1">项目列表 <a class="header-anchor" href="#项目列表" aria-label="Permalink to &quot;项目列表&quot;">​</a></h2><p><strong>项目</strong> 页展示所有项目卡片，支持以下功能：</p><ul><li><strong>搜索过滤</strong> — 按项目名称搜索</li><li><strong>术语表状态筛选</strong> — 全部 / 已启用 / 未启用</li><li><strong>排序</strong> — 按更新时间降序排列</li><li><strong>整卡进入</strong> — 点击项目卡片任意位置进入工作区；卡片上直接提供 <strong>编辑</strong>、<strong>删除</strong> 操作（删除需二次确认）</li></ul><div class="tip custom-block"><p class="custom-block-title">工作区内也能编辑项目</p><p>项目工作区标题旁有编辑入口，可直接修改项目名称、源/目标语言与术语表开关，无需返回项目列表。</p></div><h2 id="项目工作区" tabindex="-1">项目工作区 <a class="header-anchor" href="#项目工作区" aria-label="Permalink to &quot;项目工作区&quot;">​</a></h2><p>进入项目后，顶部显示项目基本信息（名称、语言方向、更新时间，标题旁有编辑入口）和统计指标栏：</p><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>资源数</td><td>项目中的文件总数</td></tr><tr><td>段落数</td><td>待翻译的内容段总数</td></tr><tr><td>已翻译</td><td>已完成翻译的段落数</td></tr><tr><td>已审核</td><td>已通过审核的段落数</td></tr><tr><td>运行中作业</td><td>正在执行的翻译作业数</td></tr></tbody></table><p>工作区（浏览态）包含四个标签页：</p><ol><li><strong>资源文件</strong> — 文件管理（详见下方），点击资源即可进入编辑视图</li><li><strong>任务</strong> — 翻译作业管理（详见下方）</li><li><strong>术语表</strong> — 项目术语管理</li><li><strong>项目存储</strong> — 当前绑定的存储空间与存储代次，支持空项目重新绑定、已有项目迁移数据（详见 <a href="/LinguaFlow/zh/guide/storage.html#项目存储绑定与迁移">存储管理 · 项目存储</a>）</li></ol><h2 id="编辑视图" tabindex="-1">编辑视图 <a class="header-anchor" href="#编辑视图" aria-label="Permalink to &quot;编辑视图&quot;">​</a></h2><p>点击任意资源（或其操作菜单的 <strong>查看段落</strong>）即进入独立的<strong>编辑视图</strong>——一个沉浸式的段落工作台，与浏览态的标签页分离：工具栏有 <strong>返回工作台</strong> 按钮，URL 也会带上资源与章节参数，可以直接分享或恢复到某个资源的某个章节。</p><p>编辑视图采用<strong>三栏布局</strong>（空间不足时侧栏自动收为抽屉）：</p><ul><li><strong>左栏 · 章节侧栏</strong>（EPUB 资源）— 列出全部章节标题与逐章进度（已译段数 / 总段数），可切换「全部章节」或具体章节</li><li><strong>中栏 · 段落列表</strong> — 翻译内容查看与编辑，支持按状态 / 质量问题筛选；段落行操作菜单可发起 <a href="/LinguaFlow/zh/guide/translation-config.html#单段试译">单段试译预览</a> / <a href="/LinguaFlow/zh/guide/translation-config.html#单段修订预览">单段修订预览</a>，满意后再应用译文</li><li><strong>右栏 · 查找 / 替换面板</strong> — 在整个资源、具体章节或选中段落范围内查找原文 / 译文并跳转定位，展开替换行可对译文批量查找替换（详见 <a href="/LinguaFlow/zh/guide/review.html#查找与定位">翻译审校 · 查找与定位</a> 与 <a href="/LinguaFlow/zh/guide/review.html#搜索替换">翻译审校 · 搜索替换</a>）</li></ul><p>段落列表滚动到底自动加载更多，无需手动点击；通过搜索跳转到中间位置后，可继续向上 / 向下加载上下文。</p><h3 id="章节批量处理" tabindex="-1">章节批量处理 <a class="header-anchor" href="#章节批量处理" aria-label="Permalink to &quot;章节批量处理&quot;">​</a></h3><p>EPUB 资源可在章节侧栏进入<strong>批量处理</strong>模式：全选 / 勾选 / 清空章节后，对所选章节发起<strong>翻译任务</strong>或 <strong>QA 重检</strong>，处理完点 <strong>退出</strong> 离开批量模式。这一入口也从原资源浏览区的 EPUB 章节目录迁到了这里。</p><h2 id="管理翻译资源" tabindex="-1">管理翻译资源 <a class="header-anchor" href="#管理翻译资源" aria-label="Permalink to &quot;管理翻译资源&quot;">​</a></h2><h3 id="上传文件" tabindex="-1">上传文件 <a class="header-anchor" href="#上传文件" aria-label="Permalink to &quot;上传文件&quot;">​</a></h3><p>支持以下方式上传文件：</p><ul><li><strong>拖拽上传</strong> — 将文件拖拽到上传区域</li><li><strong>点击上传</strong> — 点击上传按钮，通过系统文件选择器一次选取多个文件</li><li><strong>批量上传</strong> — 一次最多上传 50 个文件</li></ul><p>一次选择多个文件时，会合并为一个<strong>批次任务</strong>：上传面板按批次展示任务，而不是每个文件各占一条；状态摘要与进度按批次内文件数汇总（如「正在上传 3 个文件」），展开面板可见每个批次任务的文件名、所处阶段、上传百分比或错误信息。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>上传前会自动进行冲突检测。如果同名文件已存在，可选择替换或增量更新。</p></div><h3 id="支持的文件格式" tabindex="-1">支持的文件格式 <a class="header-anchor" href="#支持的文件格式" aria-label="Permalink to &quot;支持的文件格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>扩展名</th><th>说明</th></tr></thead><tbody><tr><td>Markdown</td><td><code>.md</code>, <code>.markdown</code>, <code>.mdx</code></td><td>通用文档格式</td></tr><tr><td>HTML</td><td><code>.html</code>, <code>.htm</code></td><td>标记语言文档</td></tr><tr><td>DOCX</td><td><code>.docx</code></td><td>Word 文档</td></tr><tr><td>EPUB</td><td><code>.epub</code></td><td>电子书格式</td></tr><tr><td>SRT</td><td><code>.srt</code></td><td>字幕格式</td></tr><tr><td>VTT</td><td><code>.vtt</code></td><td>Web 字幕格式</td></tr><tr><td>ASS</td><td><code>.ass</code></td><td>高级字幕格式</td></tr><tr><td>纯文本</td><td><code>.txt</code></td><td>纯文本文件</td></tr><tr><td>JSON</td><td><code>.json</code></td><td>JSON 结构化格式</td></tr><tr><td>YAML</td><td><code>.yaml</code>, <code>.yml</code></td><td>YAML 结构化格式</td></tr><tr><td>TOML</td><td><code>.toml</code></td><td>TOML 结构化格式</td></tr></tbody></table><p>详见 <a href="/LinguaFlow/zh/guide/formats.html">格式支持</a>。</p><h3 id="资源管理" tabindex="-1">资源管理 <a class="header-anchor" href="#资源管理" aria-label="Permalink to &quot;资源管理&quot;">​</a></h3><p>上传后的资源可以进行以下操作：</p><ul><li><strong>查看段落</strong> — 进入编辑视图，浏览与编辑翻译内容</li><li><strong>更新源文件</strong> — 替换 / 增量更新已有资源，走<strong>预览-确认</strong>流程：先看新增、原文变更、删除与未变化段落的统计，再逐个确认；每次更新生成可追踪的存储任务（详见 <a href="/LinguaFlow/zh/guide/storage.html#更新源文件">存储管理 · 更新源文件</a>）</li><li><strong>源文件与固定交付</strong> — 查看源文件版本历史（格式、大小、SHA-256），损坏原件可「同字节修复」；可把当前译文「保存为交付」固定下来，源文件再更新也不影响（详见 <a href="/LinguaFlow/zh/guide/storage.html#源文件与固定交付">存储管理 · 源文件与固定交付</a>）- <strong>下载</strong> — 下载原始文件；<strong>下载译文</strong> 把译文写回原格式导出，EPUB 译文下载前会做结构预检，存在结构缺陷时不输出文件，并在对话框中给出缺陷段落编号与原因（见 <a href="/LinguaFlow/zh/guide/review.html#结构预检">翻译审校 · 结构预检</a>）</li><li><strong>删除</strong> — 删除资源及其所有段落和翻译</li><li><strong>翻译</strong> — 勾选资源后经浮动操作栏 <strong>处理选中</strong> 启动翻译作业（EPUB 可在编辑视图章节侧栏按章节发起，见上文「章节批量处理」）</li></ul><h3 id="epub-特殊支持" tabindex="-1">EPUB 特殊支持 <a class="header-anchor" href="#epub-特殊支持" aria-label="Permalink to &quot;EPUB 特殊支持&quot;">​</a></h3><p>EPUB 与其他格式一样，点击资源即直接进入编辑视图；章节导航在编辑视图左侧的<strong>章节侧栏</strong>中，可切换全部 / 单个章节，也可按章节发起翻译任务或 QA 重检（见上文「编辑视图」）。若需统一全书横排/竖排，可使用 Web <strong>工具 → EPUB 横竖排转换</strong>（本机处理、不上传），见 <a href="/LinguaFlow/zh/guide/formats.html#epub-电子书">格式支持 · EPUB</a>。</p><h2 id="翻译作业" tabindex="-1">翻译作业 <a class="header-anchor" href="#翻译作业" aria-label="Permalink to &quot;翻译作业&quot;">​</a></h2><h3 id="创建翻译作业" tabindex="-1">创建翻译作业 <a class="header-anchor" href="#创建翻译作业" aria-label="Permalink to &quot;创建翻译作业&quot;">​</a></h3><ol><li>在项目中选择需要翻译的资源（或资源中的特定段落/章节）</li><li>选择翻译执行计划</li><li>配置作业参数： <ul><li><strong>过滤配置</strong> — 控制对已有翻译的处理方式</li><li><strong>自动审核</strong> — 翻译完成后是否自动标记为已审核</li></ul></li><li>点击 <strong>开始翻译</strong></li></ol><h3 id="过滤配置" tabindex="-1">过滤配置 <a class="header-anchor" href="#过滤配置" aria-label="Permalink to &quot;过滤配置&quot;">​</a></h3><p>创建作业时可配置段落过滤，控制哪些段落需要重新翻译：</p><table tabindex="0"><thead><tr><th>过滤选项</th><th>说明</th></tr></thead><tbody><tr><td>跳过已批准</td><td>跳过已审批通过的段落（默认）</td></tr><tr><td>覆盖未批准</td><td>覆盖所有未审批通过的段落</td></tr><tr><td>覆盖全部</td><td>覆盖所有段落，无论状态</td></tr></tbody></table><p>过滤配置可在执行计划中预设默认值，创建作业时按需覆盖。</p><h3 id="作业状态" tabindex="-1">作业状态 <a class="header-anchor" href="#作业状态" aria-label="Permalink to &quot;作业状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>等待中</td><td>作业已创建，等待执行</td></tr><tr><td>运行中</td><td>正在进行翻译</td></tr><tr><td>已暂停</td><td>被手动暂停，可随时恢复（见下方）</td></tr><tr><td>已完成</td><td>翻译完成</td></tr><tr><td>失败</td><td>翻译失败，可查看错误信息或重试</td></tr><tr><td>已取消</td><td>用户手动取消的作业</td></tr></tbody></table><h3 id="暂停与恢复" tabindex="-1">暂停与恢复 <a class="header-anchor" href="#暂停与恢复" aria-label="Permalink to &quot;暂停与恢复&quot;">​</a></h3><p>任务列表和任务详情抽屉中提供 <strong>暂停</strong> / <strong>恢复</strong> 操作：</p><ul><li><strong>暂停</strong>（等待中、运行中可用）— 优雅暂停：停止派发新批次，等待在途请求完成后冻结任务。运行中的任务需要等在途 LLM 请求收尾，界面短暂仍显示「运行中」属正常现象；等待中的任务立即变为「已暂停」</li><li><strong>恢复</strong>（已暂停可用）— 从轮次断点继续：已完成的轮次与段落直接跳过，进度计数保留，不会从头重跑</li><li>暂停不会清零进度——界面保留已完成的工作量百分比，并显示「已暂停，可随时恢复」</li><li>已暂停的任务仍可<strong>取消</strong>；暂停与取消互不替代：暂停是可恢复的中断，取消是终态（但失败/取消的任务也能通过「重试」从断点继续）</li></ul><div class="info custom-block"><p class="custom-block-title">什么场景适合暂停</p><p>LLM 速率限额即将耗尽、需要临时让出本机资源、或想在夜间低谷再继续——暂停让任务停在轮次断点，恢复后从同一位置继续，已产出译文不受影响。</p></div><h3 id="进度追踪" tabindex="-1">进度追踪 <a class="header-anchor" href="#进度追踪" aria-label="Permalink to &quot;进度追踪&quot;">​</a></h3><p>翻译过程中通过 SSE 实时推送进度信息（支持断线重连、事件持久化）：</p><ul><li><strong>翻译进度</strong> — 已完成工作量 / 总工作量（单位为「段 × 轮」，见下方「进度口径」）</li><li><strong>预计剩余时间 (ETA)</strong></li><li><strong>当前翻译速度</strong></li><li><strong>事件序号（seq）</strong> — 保证事件顺序，重连后可精准恢复丢失的事件</li></ul><h4 id="进度口径-工作量而非段落数" tabindex="-1">进度口径：工作量而非段落数 <a class="header-anchor" href="#进度口径-工作量而非段落数" aria-label="Permalink to &quot;进度口径：工作量而非段落数&quot;">​</a></h4><p>主进度按「工作量」统计：分母是已启动轮次的工作量总和（每轮 × 该轮段落数），分子是已完成部分。两点推论：</p><ul><li><strong>新轮次启动时百分比可能暂时回落</strong>——分母只计入已经启动并得知规模的轮次，后续轮次启动会扩大分母</li><li><strong>失败、取消、暂停的任务仍显示停下时的真实比例</strong>，不会归零或冻结在旧值</li><li>任务详情中<strong>失败 / 警告计数按资源数统计，跳过计数按段落数统计</strong>，与「段 × 轮」的工作量口径不同</li></ul><h4 id="任务详情-执行概览与事件日志" tabindex="-1">任务详情：执行概览与事件日志 <a class="header-anchor" href="#任务详情-执行概览与事件日志" aria-label="Permalink to &quot;任务详情：执行概览与事件日志&quot;">​</a></h4><p>任务详情抽屉分为<strong>执行概览</strong>与<strong>事件日志</strong>两个标签页：</p><ul><li><strong>进度卡</strong> — 汇总当前进度、工作量与预计剩余时间；未完成任务会把各轮次铺成可展开的流水线（收起时显示「轮 N / M」摘要），按状态着色，方便定位任务停在哪个环节</li><li><strong>资源轮次表</strong> — 每个资源一行，展开可查看该资源的逐轮明细：轮次模式（翻译、语义质检等）、各状态计数、轮次序号、段落数、起止时间与错误信息；被暂停 / 停止 / 未执行的轮次有对应的状态图标，收起时汇总展示各资源的轮次完成情况（如「完成 3 轮 · 跳过 1 轮」）</li><li><strong>更多信息</strong> — 创建 / 更新时间等元数据折叠展示，错误信息会直接显示在概览顶部</li></ul><p>作业详情中的 <strong>事件日志</strong> 会把这些事件按 <code>seq</code> 顺序铺成一条可滚动的时间线：</p><ul><li><strong>历史 / 实时分离</strong> — 打开已结束的任务时加载历史记录，可点 <strong>加载更早记录</strong> 向前翻页；任务运行中则通过 SSE 实时追加新事件，离开当前视野的新事件会汇总为「查看 N 条新记录」按钮，连接断开时显示「未连接」</li><li><strong>异常筛选</strong> — 「全部 / 异常」一键过滤失败、警告等异常记录（仅作用于已加载的记录），排错时不必在正常事件里翻找</li><li><strong>批次事件卡</strong> — 每个批次翻译事件以卡片形式展示状态与摘要，<strong>点击卡片</strong> 打开右侧 <strong>批次详情抽屉</strong></li><li><strong>批次详情抽屉</strong> — 展示该批次的完整元数据：状态、错误信息、发送 / 接收内容、术语使用情况，以及截断 / 解析修复诊断标签（见 <a href="/LinguaFlow/zh/guide/review.html#截断与修复诊断">翻译审校 · 截断与修复诊断</a>），便于排错与复盘</li><li><strong>跳过状态</strong> — 因目标段状态不满足 <code>segment_filter</code> 而未执行的批次，会标记为 <code>skipped</code>（信息色），与成功 / 部分成功 / 失败区分</li><li><strong>清空当前日志</strong> — 一键清空已加载的事件记录</li></ul><div class="tip custom-block"><p class="custom-block-title">历史事件也可查询</p><p>任务事件不仅能在界面里看，也有对应的 REST 分页端点（按 <code>seq</code> 游标双向翻页），便于外部监控或导出。详见 <a href="/LinguaFlow/zh/api/#_9-任务事件历史-分页">API 概述 · 任务事件</a>。</p></div><h3 id="作业操作" tabindex="-1">作业操作 <a class="header-anchor" href="#作业操作" aria-label="Permalink to &quot;作业操作&quot;">​</a></h3><ul><li><strong>暂停 / 恢复</strong> — 见上方「暂停与恢复」</li><li><strong>取消</strong> — 取消等待中、运行中或已暂停的作业（终态）</li><li><strong>重试</strong> — 对失败或已取消的作业重新执行：失败/取消的资源重新入队，已完成轮次与已翻译段落直接跳过，从当前进度断点继续。例外：显式手选段落的任务，首个翻译轮会重译所有选中段落</li></ul><div class="tip custom-block"><p class="custom-block-title">服务重启不用重来</p><p>服务升级或重启时，运行中的任务会在下次启动时自动恢复执行，已完成的轮次与译文保留；也可以在任务中心或详情抽屉手动 <strong>重试</strong>。</p></div><h2 id="任务中心-跨项目任务列表" tabindex="-1">任务中心（跨项目任务列表） <a class="header-anchor" href="#任务中心-跨项目任务列表" aria-label="Permalink to &quot;任务中心（跨项目任务列表）&quot;">​</a></h2><p>顶栏的 <strong>任务中心</strong> 把你有权限查看的翻译、术语同步与<strong>文件存储</strong>任务（文件上传 / 源文件更新 / 同字节修复）<strong>跨项目</strong>汇总在一页：支持按任务类型、状态、项目、触发来源与更新时间区间过滤，点击条目直接打开对应任务详情（含取消 / 重试 / 暂停 / 恢复操作）。文件存储任务的阶段与清理状态说明见 <a href="/LinguaFlow/zh/guide/storage.html#存储任务">存储管理 · 存储任务</a>。</p><ul><li>任务可见性跟随项目读权限；服务器模式下，同组织成员可以看到同一项目内其他成员创建的任务</li><li>状态汇总卡片展示各状态任务数与近 7 天失败数</li><li>长任务不必停在项目页——页头的 <strong>当前任务</strong> 按钮弹出追踪面板，显示活动任务数与「失败提醒 / 需要处理 / 等待自动重试」计数，可清除已结束任务、隐藏提醒，空闲时只留图标</li></ul><div class="info custom-block"><p class="custom-block-title">操作前会保护未保存内容</p><p>有未保存的译文或备注时发起源文件更新等操作，会先弹出保存确认；登录态或归属变化后操作会被拦截，结果未知时引导查看原任务，避免重复提交。详见 <a href="/LinguaFlow/zh/guide/storage.html#会话与草稿保护">存储管理 · 会话与草稿保护</a>。</p></div><h2 id="项目设置" tabindex="-1">项目设置 <a class="header-anchor" href="#项目设置" aria-label="Permalink to &quot;项目设置&quot;">​</a></h2><h3 id="语言设置" tabindex="-1">语言设置 <a class="header-anchor" href="#语言设置" aria-label="Permalink to &quot;语言设置&quot;">​</a></h3><ul><li>修改源语言和目标语言</li><li>切换源语言自动识别</li></ul><h3 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h3><p>将术语表关联到项目，翻译时自动应用术语规则。启用后，翻译引擎会优先使用术语表中的翻译结果。</p><p>详见 <a href="/LinguaFlow/zh/guide/glossary.html">术语表管理</a>。</p><h2 id="项目删除" tabindex="-1">项目删除 <a class="header-anchor" href="#项目删除" aria-label="Permalink to &quot;项目删除&quot;">​</a></h2><p>删除项目时会<strong>级联删除</strong>以下所有关联数据：</p><ul><li>翻译作业及其关联关系</li><li>资源文件及其段落</li><li>术语表条目</li><li>翻译记忆条目</li><li>同步任务记录</li><li>活动日志和使用记录</li></ul><div class="tip custom-block"><p class="custom-block-title">活动日志的两种视角</p><p>项目内的「活动」是当前用户视角的过滤视图。服务器模式下，管理员可在 <a href="/LinguaFlow/zh/guide/admin.html#审计日志">管理员后台 · 审计日志</a> 查看全局审计记录。</p></div><div class="danger custom-block"><p class="custom-block-title">警告</p><p>项目删除操作不可撤销，请谨慎操作。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>阅读 <a href="/LinguaFlow/zh/guide/translation-config.html">翻译配置 · 使用</a> 了解如何优化翻译效果</li><li>阅读 <a href="/LinguaFlow/zh/guide/glossary.html">术语表管理</a> 了解术语管理</li><li>阅读 <a href="/LinguaFlow/zh/guide/review.html">翻译审校</a> 了解翻译质量控制</li></ul>',88)])])}const p=o(d,[["render",e]]);export{u as __pageData,p as default};
